\definecolor{primary}{HTML}{1D4ED8} % Blue 700 (Title bar, accents)
\definecolor{secondary}{HTML}{0284C7} % Light blue / Cyan
\definecolor{accentgreen}{HTML}{10B981} % Emerald 500
